===== Localities =====
package org.springframework.samples.petclinic.mapper;

import java.util.Map;

/**
 * Derives an owner's {@code locality} (region) preferring the postcode over the city.
 *
 * <p>The region is resolved by postcode range first (NSW 2000-2099, VIC 3000-3099,
 * QLD 4000-4099); only when the postcode is absent or in no known range does it fall
 * back to a fixed city-to-region table. Anything unresolved maps to {@code UNKNOWN}.
 * This yields the same region for known cities but disambiguates cities that share a
 * name.
 */
public final class Localities {

    private static final Map<String, String> CITY_REGION = Map.of(
        "Sydney", "NSW",
        "Melbourne", "VIC",
        "Brisbane", "QLD");

    /** Region -> inclusive {low, high} 4-digit postcode range. */
    private static final Map<String, int[]> REGION_RANGE = Map.of(
        "NSW", new int[] {2000, 2099},
        "VIC", new int[] {3000, 3099},
        "QLD", new int[] {4000, 4099});

    private Localities() {
    }

    /** The canonical region for the given city, or {@code UNKNOWN} when unlisted. */
    public static String forCity(String city) {
        return CITY_REGION.getOrDefault(city, "UNKNOWN");
    }

    /**
     * The region whose postcode range contains the given 4-digit postcode, or
     * {@code null} when the postcode is absent, malformed, or in no known range.
     */
    public static String forPostcode(String postcode) {
        if (postcode == null || postcode.isBlank()) {
            return null;
        }
        int value;
        try {
            value = Integer.parseInt(postcode.trim());
        }
        catch (NumberFormatException ex) {
            return null;
        }
        for (Map.Entry<String, int[]> entry : REGION_RANGE.entrySet()) {
            int[] range = entry.getValue();
            if (value >= range[0] && value <= range[1]) {
                return entry.getKey();
            }
        }
        return null;
    }

    /**
     * The region for an owner, preferring the postcode range and falling back to the
     * city-to-region table when the postcode is absent or in no known range.
     */
    public static String forCityAndPostcode(String city, String postcode) {
        String byPostcode = forPostcode(postcode);
        return byPostcode != null ? byPostcode : forCity(city);
    }
}
===== MembershipLevels =====
package org.springframework.samples.petclinic.mapper;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Derives an owner's numeric {@code membershipLevel} (1-3) from its create-time
 * attributes: start at 1, add 1 when an email is present, add 1 when
 * {@code namesakeCount} is 0, capped at 3. Level 4 is reserved for tenure.
 */
public final class MembershipLevels {

    private MembershipLevels() {
    }

    /** The membership level (1-3) for the given owner. */
    public static int forOwner(Owner owner) {
        int level = 1;
        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
            level++;
        }
        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
            level++;
        }
        return Math.min(level, 3);
    }
}
===== Postcodes =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Map;
import java.util.regex.Pattern;

import org.springframework.samples.petclinic.mapper.Localities;

/**
 * Validates an owner's optional postcode against its city's region.
 *
 * <p>A postcode, when supplied, must be exactly 4 digits and fall within the
 * inclusive range fixed for the region derived from the owner's city
 * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region
 * (locality {@code UNKNOWN}) accepts any 4-digit postcode.
 */
public final class Postcodes {

    private static final Pattern FOUR_DIGITS = Pattern.compile("^[0-9]{4}$");

    /** Region -> inclusive {low, high} 4-digit postcode range. */
    private static final Map<String, int[]> REGION_RANGE = Map.of(
        "NSW", new int[] {2000, 2099},
        "VIC", new int[] {3000, 3099},
        "QLD", new int[] {4000, 4099});

    private Postcodes() {
    }

    /**
     * Whether the postcode is acceptable for the given city. A blank/absent postcode
     * is acceptable (validated only when present). When present it must be 4 digits and,
     * for a city with a known region, within that region's range.
     */
    public static boolean isValid(String postcode, String city) {
        if (postcode == null || postcode.isBlank()) {
            return true;
        }
        if (!FOUR_DIGITS.matcher(postcode).matches()) {
            return false;
        }
        int[] range = REGION_RANGE.get(Localities.forCity(city));
        if (range == null) {
            return true;
        }
        int value = Integer.parseInt(postcode);
        return value >= range[0] && value <= range[1];
    }
}
===== IdentityKeys =====
package org.springframework.samples.petclinic.rest.function.owner;

import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Computes an owner's {@code identityKey}: the single derived value all duplicate detection
 * is expressed through. The key is
 * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}.
 *
 * <p>Two owners are duplicates only when their WHOLE keys are equal (see
 * {@link RequireUniqueIdentity}). Because the telephone is part of the key, two members of
 * the same household (same {@code householdId}) with different telephones have different
 * keys and are both allowed; only an exact full-key match is a conflict.
 *
 * <ul>
 * <li>telephone is normalized to E.164 form ({@link Telephones#toE164(String)}),
 * <li>email is trimmed and lower-cased, contributing empty when absent,
 * <li>householdId is the owner's shared-household identifier, empty when the owner is not
 *     part of a shared household.
 * </ul>
 */
public final class IdentityKeys {

    private IdentityKeys() {
    }

    /** The identity key of an existing owner, from its stored fields. */
    public static String forOwner(Owner owner) {
        return build(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
    }

    /** The prospective identity key of an incoming create request. */
    public static String forRequest(OwnerFieldsDto request) {
        String householdId = Boolean.TRUE.equals(request.getSharesHousehold())
                ? Households.idFor(request.getLastName(), request.getAddress())
                : null;
        return build(request.getTelephone(), request.getEmail(), householdId);
    }

    private static String build(String telephone, String email, String householdId) {
        String tel = Telephones.toE164(telephone);
        return (tel == null ? "" : tel) + "|" + normalizeEmail(email) + "|"
                + (householdId == null ? "" : householdId);
    }

    /** Trim and lower-case; null or blank yields empty (no email to contribute). */
    private static String normalizeEmail(String email) {
        if (email == null || email.isBlank()) {
            return "";
        }
        return email.trim().toLowerCase();
    }
}

